    public int threeSumSmaller(int[] nums, int target) {
        Arrays.sort(nums);
        int count = 0;

        for (int right = 2; right < nums.length; right++) {
            int left = 0;
            int middle = right - 1;
            while (left < middle) {
                int sum = nums[left] + nums[middle] + nums[right];
                if (sum < target) {
                    count += middle - left;
                    left++;
                } else {
                    middle--;
                }
            }
        }

        return count;
    }
}

class Solution {
    public int threeSumSmaller(int[] nums, int target) {
        Arrays.sort(nums);
        int count = 0;

        for (int i = 0; i < nums.length - 2; i++) {
            for (int j = i + 1; j < nums.length - 1; j++) {
                int limit = target - nums[i] - nums[j];
                int firstTooLarge = lowerBound(nums, j + 1, nums.length, limit);
                count += firstTooLarge - (j + 1);
            }
        }

        return count;
    }

    private int lowerBound(int[] nums, int left, int right, int target) {
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] >= target) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
}

class Solution {
    public int threeSumSmaller(int[] nums, int target) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                for (int k = j + 1; k < nums.length; k++) {
                    if (nums[i] + nums[j] + nums[k] < target) {
                        count++;
                    }
                }
            }
        }
        return count;
    }
}
